Q: Sinon stub being skipped as node express middleware
A: <p>There is an issue indeed with stubbing your code.</p>

<p>When you require your server file</p>

<pre><code>const app = require('../server/server.js');
</code></pre>

<p>your app is get created with the whole set of middlewares, including <code>rejectUnauthenticated</code>, and a reference to the latter is stored inside <code>app</code>.</p>

<p>When you do</p>

<pre><code>sinon.stub(authenticationMiddleware, 'rejectUnauthenticated')
  .callsFake(async (req, res, next) =&gt; next());
</code></pre>

<p>you replace the <code>rejectUnauthenticated</code> exported method of <code>authenticationMiddleware</code> module, but not the reference to original <code>rejectUnauthenticated</code> that is already stored.</p>

<p>The solution is to create the app (i.e. <code>require('../server/server.js');</code>) <em>after</em> you mock the exoprted middleware method:</p>

<pre><code>const chai = require('chai');
const chaiHttp = require('chai-http');
const sinon = require('sinon');

// don't create app right away
let app;
const authenticationMiddleware = require('../server/modules/event-authentication.middleware');

const { expect } = chai;
chai.use(chaiHttp);

describe('with correct secret key', () =&gt; {
  it('should return bracket', (done) =&gt; {
    sinon.stub(authenticationMiddleware, 'rejectUnauthenticated')
      .callsFake(async (req, res, next) =&gt; next());

    // method is stubbed, you can create app now
    app = require('../server/server.js');

    chai.request(app)
      .get('/code-championship/registrant/event')
      .

